SELECT `id`,`device_sn`,`shipment_time`,`package_no`,`contract_no`,`event_type`,`warranty_start_date`,`warranty_months`,`rma_no`,`related_device_sn`,`source_system`,`source_key`,`source_version`,`source_updated_at`,`synced_at`,`sync_status`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`legacy_package_key`,`rma_related_sn`,`rma_marked`,`order_line_id`,`source_payload`,`order_no`,`line_no`,`product_code`,`secondary_sn`,`secondary_item`,`internal_serial_no`,`is_rma`,`profit_center`,`sole_agent_suffix`,`sync_time`,`uuid` FROM ast_device_shipment WHERE tenant_id=#{query.tenantId} AND source_system='DPPMS'  /* CHOOSE  */ /* WHEN test=query.keys != null and !query.keys.isEmpty() */ AND source_key IN  /* FOREACH collection=query.keys; item=key; open=(; close=); separator=, */ (#{key}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  /* IF test=!query.preview */ FOR UPDATE /* END IF */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.insertShipmentEvent; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:90; kind=insert
INSERT INTO ast_device_shipment (`id`,`device_sn`,`shipment_time`,`package_no`,`contract_no`,`event_type`,`warranty_start_date`,`warranty_months`,`rma_no`,`related_device_sn`,`source_system`,`source_key`,`source_version`,`source_updated_at`,`synced_at`,`sync_status`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`legacy_package_key`,`rma_related_sn`,`rma_marked`,`order_line_id`,`source_payload`,`order_no`,`line_no`,`product_code`,`secondary_sn`,`secondary_item`,`internal_serial_no`,`is_rma`,`profit_center`,`sole_agent_suffix`,`sync_time`,`uuid`) VALUES  /* FOREACH collection=rows; item=row; separator=, */ (#{row.target.id},#{row.target.deviceSn},#{row.target.shipmentTime},#{row.target.packageNo},#{row.target.contractNo},#{row.target.eventType},#{row.target.warrantyStartDate},#{row.target.warrantyMonths},#{row.target.rmaNo},#{row.target.relatedDeviceSn},#{row.target.sourceSystem},#{row.target.sourceKey},#{row.target.sourceVersion},#{row.target.sourceUpdatedAt},#{row.target.syncedAt},#{row.target.syncStatus},#{row.target.version},#{row.target.creator},#{row.target.createTime},#{row.target.updater},#{row.target.updateTime},#{row.target.deleted},#{row.target.tenantId},#{row.target.legacyPackageKey},#{row.target.rmaRelatedSn},#{row.target.rmaMarked},#{row.target.orderLineId},#{row.target.sourcePayload},#{row.target.orderNo},#{row.target.lineNo},#{row.target.productCode},#{row.target.secondarySn},#{row.target.secondaryItem},#{row.target.internalSerialNo},#{row.target.isRma},#{row.target.profitCenter},#{row.target.soleAgentSuffix},#{row.target.syncTime},#{row.target.uuid}) /* repeat with separator=,; END FOREACH */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.selectRelationships; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:91; kind=select
SELECT `id`,`source_device_sn`,`target_device_sn`,`relationship_type`,`contract_no`,`effective_from`,`effective_to`,`source_system`,`source_key`,`source_version`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`source_item`,`target_item` FROM ast_device_relationship WHERE tenant_id=#{query.tenantId} AND source_system='DPPMS'  /* CHOOSE  */ /* WHEN test=query.keys != null and !query.keys.isEmpty() */ AND source_key IN  /* FOREACH collection=query.keys; item=key; open=(; close=); separator=, */ (#{key}) /* repeat with separator=,; END FOREACH */ /* END WHEN */  /* OTHERWISE  */ AND 1=0 /* END OTHERWISE */ /* END CHOOSE */  /* IF test=!query.preview */ FOR UPDATE /* END IF */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.insertDeviceRelationship; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:92; kind=insert
INSERT INTO ast_device_relationship (`id`,`source_device_sn`,`target_device_sn`,`relationship_type`,`contract_no`,`effective_from`,`effective_to`,`source_system`,`source_key`,`source_version`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`source_item`,`target_item`) VALUES  /* FOREACH collection=rows; item=row; separator=, */ (#{row.target.id},#{row.target.sourceDeviceSn},#{row.target.targetDeviceSn},#{row.target.relationshipType},#{row.target.contractNo},#{row.target.effectiveFrom},#{row.target.effectiveTo},#{row.target.sourceSystem},#{row.target.sourceKey},#{row.target.sourceVersion},#{row.target.version},#{row.target.creator},#{row.target.createTime},#{row.target.updater},#{row.target.updateTime},#{row.target.deleted},#{row.target.tenantId},#{row.target.sourceItem},#{row.target.targetItem}) /* repeat with separator=,; END FOREACH */;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.selectCarriers; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:93; kind=select
SELECT value AS code,label FROM system_dict_data WHERE dict_type='01' AND deleted=FALSE AND status=0;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.packageSourceColumnReady; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:94; kind=select
SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='com_shipment_package' AND column_name='shipment_contract_source_key' AND data_type='varchar' AND character_maximum_length>=64;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$TargetMapper.latestP24Execution; pms-module-integration/src/main/resources/mapper/basesync/P15TargetMapper.xml:95; kind=select
SELECT r.status FROM int_base_sync_run r JOIN int_base_sync_task t ON t.tenant_id=r.tenant_id AND t.id=r.task_id AND t.deleted=FALSE WHERE r.tenant_id=#{query.tenantId} AND r.connection_id=#{query.connectionId} AND r.task_code='BASE_P24' AND r.preview=FALSE AND r.deleted=FALSE ORDER BY r.id DESC LIMIT 1;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectShipmentContract; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:5; kind=select
SELECT f.contract_id AS raw_key,f.warranty AS raw_warranty,'DPPMS' AS `source_system`,f.contract_id AS `source_record_key`,f.contract_code AS `contract_no`,f.office_code AS `department_code`,CAST(f.contract_type AS CHAR) AS `contract_type`,f.customer_name AS `customer_name`,f.project_name AS `project_name`,f.marketCode AS `market_code`,f.marketName AS `market_name`,CAST(f.systemId AS CHAR) AS `system_source_key`,f.systemName AS `system_name`,f.remark AS `remark` FROM fb_contract f WHERE NOT ((f.contract_id IS NULL OR TRIM(f.contract_id)='') AND (f.contract_code IS NULL OR TRIM(f.contract_code)='')) LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectPackage; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:8; kind=select
SELECT p.packlist_id AS raw_key,'DPPMS' AS `source_system`,p.packlist_id AS `source_record_key`,p.packlist_id AS `package_no`,p.packdate AS `shipment_time`,p.warrantyStartTime AS `warranty_start_time`,p.warrantyEndTime AS `warranty_end_time`,p.receiveName AS `receiver_name`,p.emsNum AS `express_no`,p.emsCompany AS `carrier_code`,p.con_id AS `shipment_contract_source_key` FROM fb_shipment p LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectShipmentEvent; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:11; kind=select
SELECT CAST(b.id AS CHAR) AS raw_key,'DPPMS' AS `source_system`,CAST(b.id AS CHAR) AS `source_key`,b.barcode AS `device_sn`,b.pack_id AS `package_no`,b.pack_id AS `legacy_package_key`,CASE WHEN COALESCE(b.rma_no,'')<>'' THEN 'UNCLASSIFIED' ELSE 'SHIPMENT' END AS `event_type`,CASE WHEN COALESCE(b.rma_no,'')<>'' THEN 1 ELSE 0 END AS `rma_marked`,b.warrantyStartDate AS `warranty_start_date`,b.warrantyMonth AS `warranty_months`,b.rma_no AS `rma_no`,b.rmaBarcode AS `rma_related_sn`,b.updateTime AS `source_updated_at`,b.orderNumber AS `order_no`,CAST(b.lineNum AS CHAR) AS `line_no`,b.item AS `product_code`,b.barcode2 AS `secondary_sn`,b.item2 AS `secondary_item`,b.com_barcode AS `internal_serial_no`,b.isRMA AS `is_rma`,b.profitCenter AS `profit_center`,b.soleAgentSuffix AS `sole_agent_suffix`,b.syncTime AS `sync_time`,b.uuid AS `uuid` FROM fb_shipment_barcode b ORDER BY b.id LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectDeviceRelationship; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:14; kind=select
SELECT CAST(r.id AS CHAR) AS raw_key,'DPPMS' AS `source_system`,CAST(r.id AS CHAR) AS `source_key`,r.sn1 AS `source_device_sn`,r.sn2 AS `target_device_sn`,'EXTRA_SN' AS `relationship_type`,r.contract AS `contract_no`,r.createtime AS `raw_relationship_created_at`,r.updatetime AS `source_version`,r.item1 AS `source_item`,r.item2 AS `target_item` FROM fb_shipment_barcode_relation r WHERE r.sn1<>r.sn2 ORDER BY r.id LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.countShipmentEvents; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:16; kind=select
SELECT COUNT(*) FROM fb_shipment_barcode;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectContractCustomers; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:17; kind=select
SELECT CAST(JSON_ARRAY(CASE r.compCode WHEN '01' THEN '001' WHEN '02' THEN '002' WHEN '03' THEN '003' WHEN '04' THEN '004' ELSE r.compCode END,r.contractNo) AS CHAR) AS raw_key,
 CASE r.compCode WHEN '01' THEN '001' WHEN '02' THEN '002' WHEN '03' THEN '003' WHEN '04' THEN '004' ELSE r.compCode END AS company_code,r.contractNo AS contract_no,r.customerName AS customer_name,
 CASE WHEN r.customerCode IS NULL OR r.customerCode='' THEN r.customerCode
 WHEN r.customerCode REGEXP '^[A-Za-z]' AND CHAR_LENGTH(TRIM(LEADING '0' FROM SUBSTRING(r.customerCode,2)))<=5
 THEN CONCAT(LEFT(r.customerCode,1),LPAD(TRIM(LEADING '0' FROM SUBSTRING(r.customerCode,2)),5,'0')) ELSE NULL END AS customer_code,
 CASE WHEN r.customerCode IS NOT NULL AND r.customerCode<>'' AND (NOT(r.customerCode REGEXP '^[A-Za-z]') OR CHAR_LENGTH(TRIM(LEADING '0' FROM SUBSTRING(r.customerCode,2)))>5) THEN 'ERP_CUSTOMER_CODE_FORMAT_INVALID' ELSE NULL END AS issue
FROM pm_order_data_from_erp r WHERE r.source IN ('SAP','D365','SMS') AND r.compCode IS NOT NULL AND r.compCode<>'' AND r.contractNo IS NOT NULL AND r.contractNo<>''
ORDER BY r.id LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectContractShipmentFields; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:27; kind=select
SELECT s.contract_code AS contract_no,
SUBSTRING(MAX(CASE WHEN s.`project_name` IS NOT NULL AND CAST(s.`project_name` AS CHAR)<>'' THEN CONCAT(RPAD(s.contract_id,64,' '),CAST(s.`project_name` AS CHAR)) END),65) AS `project_name`,
SUBSTRING(MAX(CASE WHEN s.`marketCode` IS NOT NULL AND CAST(s.`marketCode` AS CHAR)<>'' THEN CONCAT(RPAD(s.contract_id,64,' '),CAST(s.`marketCode` AS CHAR)) END),65) AS `market_code`,
SUBSTRING(MAX(CASE WHEN s.`marketName` IS NOT NULL AND CAST(s.`marketName` AS CHAR)<>'' THEN CONCAT(RPAD(s.contract_id,64,' '),CAST(s.`marketName` AS CHAR)) END),65) AS `market_name`,
SUBSTRING(MAX(CASE WHEN s.`office_code` IS NOT NULL AND CAST(s.`office_code` AS CHAR)<>'' THEN CONCAT(RPAD(s.contract_id,64,' '),CAST(s.`office_code` AS CHAR)) END),65) AS `department_code`,
SUBSTRING(MAX(CASE WHEN s.`systemName` IS NOT NULL AND CAST(s.`systemName` AS CHAR)<>'' THEN CONCAT(RPAD(s.contract_id,64,' '),CAST(s.`systemName` AS CHAR)) END),65) AS `system_name`
FROM fb_contract s WHERE NOT ((s.contract_id IS NULL OR TRIM(s.contract_id)='') AND (s.contract_code IS NULL OR TRIM(s.contract_code)='')) GROUP BY s.contract_code LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectContractReceivableFields; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:36; kind=select
SELECT s.contract_num AS contract_no,
SUBSTRING(MAX(CASE WHEN s.`currency_name` IS NOT NULL AND CAST(s.`currency_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`currency_name` AS CHAR)) END),40) AS `currency_name`,
SUBSTRING(MAX(CASE WHEN s.`contract_money_amount` IS NOT NULL AND CAST(s.`contract_money_amount` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`contract_money_amount` AS CHAR)) END),40) AS `contract_amount`,
SUBSTRING(MAX(CASE WHEN s.`contract_create_date` IS NOT NULL AND CAST(s.`contract_create_date` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`contract_create_date` AS CHAR)) END),40) AS `contract_create_time`,
SUBSTRING(MAX(CASE WHEN s.`project_name` IS NOT NULL AND CAST(s.`project_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`project_name` AS CHAR)) END),40) AS `project_name`,
SUBSTRING(MAX(CASE WHEN s.`projectCode` IS NOT NULL AND CAST(s.`projectCode` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`projectCode` AS CHAR)) END),40) AS `project_code`,
SUBSTRING(MAX(CASE WHEN s.`marketCode` IS NOT NULL AND CAST(s.`marketCode` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`marketCode` AS CHAR)) END),40) AS `market_code`,
SUBSTRING(MAX(CASE WHEN s.`maketing_department_name` IS NOT NULL AND CAST(s.`maketing_department_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`maketing_department_name` AS CHAR)) END),40) AS `market_name`,
SUBSTRING(MAX(CASE WHEN s.`officeCode` IS NOT NULL AND CAST(s.`officeCode` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`officeCode` AS CHAR)) END),40) AS `department_code`,
SUBSTRING(MAX(CASE WHEN s.`office_name` IS NOT NULL AND CAST(s.`office_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`office_name` AS CHAR)) END),40) AS `department_name`,
SUBSTRING(MAX(CASE WHEN s.`industryId` IS NOT NULL AND CAST(s.`industryId` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`industryId` AS CHAR)) END),40) AS `industry_code`,
SUBSTRING(MAX(CASE WHEN s.`industry_name` IS NOT NULL AND CAST(s.`industry_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`industry_name` AS CHAR)) END),40) AS `industry_name`,
SUBSTRING(MAX(CASE WHEN s.`usernamec` IS NOT NULL AND CAST(s.`usernamec` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`usernamec` AS CHAR)) END),40) AS `marketing_representative_code`,
SUBSTRING(MAX(CASE WHEN s.`marketing_representative_name` IS NOT NULL AND CAST(s.`marketing_representative_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`marketing_representative_name` AS CHAR)) END),40) AS `marketing_representative_name`,
SUBSTRING(MAX(CASE WHEN s.`usernamec2` IS NOT NULL AND CAST(s.`usernamec2` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(s.update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(s.id AS CHAR),20,'0')),CAST(s.`usernamec2` AS CHAR)) END),40) AS `secondary_representative_code`
FROM sms_ofst_contract_head_sap s WHERE s.contract_num IS NOT NULL GROUP BY s.contract_num LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectShipmentPackageReferences; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:54; kind=select
SELECT packlist_id AS source_key,con_id AS contract_source_key,packdate AS shipment_time FROM fb_shipment LIMIT #{limit};

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P15DeliverySyncTask$SourceMapper.selectShipmentContractReferences; pms-module-integration/src/main/resources/base-sync-source/P15SourceMapper.xml:57; kind=select
SELECT contract_id AS source_key,contract_code AS contract_no FROM fb_contract WHERE NOT ((contract_id IS NULL OR TRIM(contract_id)='') AND (contract_code IS NULL OR TRIM(contract_code)='')) LIMIT #{limit};
